{"status":"completed","exit_code":0,"stdout":"      tags_before: ${{ steps.plan.outputs.tags_before }}
    steps:
      - name: Checkout the default branch, which decides what may be deployed
        uses: actions/checkout@v4
        with:
          ref: ${{ github.event.repository.default_branch }}
      - name: Setup Bun
        with:
          bun-version: latest
        uses: oven-sh/setup-bun@v2
      - name: Read `deploy` and select what this run is for
        id: plan
        shell: bash
        env:
          ATOMATON_DEPLOY_REF: ${{ github.ref }}
          ATOMATON_DEPLOY_EVENT: ${{ github.event_name }}
          ATOMATON_DEPLOY_TRIGGER: ${{ inputs.trigger }}
          ATOMATON_DEPLOY_TARGET_INPUT: ${{ inputs.target }}
          ATOMATON_DEFAULT_BRANCH: ${{ github.event.repository.default_branch }}
          ATOMATON_REPO: ${{ github.repository }}
          ATOMATON_PUSH_BEFORE: ${{ github.event.before }}
          GH_TOKEN: ${{ github.token }}
        run: |
          PLANNER="${ATOMATON_MACHINERY_ROOT:-.}/.github/atomaton-runtime/scripts/plan_deploy.ts"
          if [ ! -f "$PLANNER" ]; then
            echo "::warning::$PLANNER is not on the default branch yet, so nothing could be planned and nothing was deployed. This is expected once, on the upgrade that adds it."
            echo "jobs=[]" >> "$GITHUB_OUTPUT"
            exit 0
          fi
          bun run "${ATOMATON_MACHINERY_ROOT:-.}/.github/atomaton-runtime/scripts/plan_deploy.ts" --ref "${ATOMATON_DEPLOY_REF}" --default-branch "${ATOMATON_DEFAULT_BRANCH}" --event "${ATOMATON_DEPLOY_EVENT}" --trigger "${ATOMATON_DEPLOY_TRIGGER}" --target "${ATOMATON_DEPLOY_TARGET_INPUT}" --repo "${ATOMATON_REPO}" --before "${ATOMATON_PUSH_BEFORE}"
  deploy:
","stderr":"","output_truncated":false,"execution_time_ms":90}

