{"command":"set -euo pipefail
bump() { echo "${1%.*}.$(( ${1##*.} + 1 ))"; }
for v in 0.2.9 0.2.3 1.0.0 0.3.0-rc.1 0.3.0-rc.9; do echo "$v -> $(bump "$v")"; done
echo "--- strips v, then validates:"
for v in v0.2.9 "0.2.9" "1.2" "abc"; do NEW="${v#v}"; if [[ "$NEW" =~ ^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?$ ]]; then echo "$v OK"; else echo "$v REJECTED"; fi; done","working_directory":"/home/runner/work/atomaton/atomaton"}
